// מעבד אירועי webhook מאינסטגרם ושומר את מצב השיחות בזיכרון של ה-workflow.
// סטטוסים: active = הבוט עונה, handoff = מחכה לאביב, human = אביב ענה בעצמו, optout = לא מעוניין.
const cfg = $('Config').first().json;
const state = $getWorkflowStaticData('global');
state.convos = state.convos || {};
const body = $('הודעה נכנסת').first().json.body || {};
const mark = (cfg.OPENER_MARK || '').trim();
const out = [];

for (const entry of body.entry || []) {
  for (const ev of entry.messaging || []) {
    const msg = ev.message;
    if (!msg || msg.is_deleted) continue;
    const text = (msg.text || (msg.attachments ? '[צרף קובץ/תמונה]' : '')).trim();
    if (!text) continue;

    if (msg.is_echo) {
      // הודעה שיצאה מהחשבון של אביב (מהטלפון או מהבוט)
      const other = ev.recipient.id;
      let c = state.convos[other];
      if (!c) {
        // מצב בדיקה: MAX_CONVERSATIONS מגביל כמה שיחות הבוט פותח בכלל (ריק = בלי הגבלה).
        const max = parseInt(cfg.MAX_CONVERSATIONS, 10);
        const full = max > 0 && Object.keys(state.convos).length >= max;
        if (mark && text.includes(mark) && !full) {
          state.convos[other] = { status: 'active', opened: Date.now(), history: [{ who: 'אביב', text }], botTexts: [] };
        }
        continue;
      }
      const i = c.botTexts.indexOf(text);
      if (i !== -1) { c.botTexts.splice(i, 1); continue; } // הד של הודעה שהבוט שלח
      c.history.push({ who: 'אביב', text });
      const barberWrote = c.history.some((h) => h.who === 'ספר');
      // הודעות הפתיחה נשלחות כמה ברצף: עד שהספר עונה, הודעות של אביב הן עוד חלק מהפתיחה.
      if (barberWrote && (c.status === 'active' || c.status === 'handoff')) c.status = 'human'; // אביב נכנס לשיחה, הבוט זז הצידה
      continue;
    }

    const igsid = ev.sender.id;
    const c = state.convos[igsid];
    if (!c) continue; // לא ליד שאביב פתח מולו שיחה, הבוט לא נוגע
    c.history.push({ who: 'ספר', text });
    c.history = c.history.slice(-30);
    c.lastMid = msg.mid;
    c.lastAt = Date.now();
    if (c.status === 'active') {
      out.push({ json: { igsid, mid: msg.mid } });
    } else if (c.status === 'handoff') {
      out.push({ json: { igsid, mid: msg.mid, notifyOnly: true } });
    }
  }
}
return out;

// מחכים קצת כי ספרים שולחים כמה הודעות ברצף. עונים רק על האחרונה.
const state = $getWorkflowStaticData('global');
return $input.all().filter((it) => {
  const c = state.convos?.[it.json.igsid];
  return c && c.lastMid === it.json.mid;
});

const state = $getWorkflowStaticData('global');
const cfg = $('Config').first().json;
const trialOn = String(cfg.TRIAL_ENABLED).toLowerCase() === 'true';
return $input.all().map((it) => {
  const c = state.convos[it.json.igsid];
  const transcript = c.history.map((h) => h.who + ': ' + h.text).join('\n');
  let rule;
  if (c.trialSlug) {
    rule = 'כבר שלחת לו לינק לאפליקציה שלו: ' + c.trialUrl + ' . שבוע הניסיון בחינם נגמר ב-' + c.trialEndsHe + '. עזור לו עם שאלות על האפליקציה. מחיר וסגירה: handoff.';
  } else if (!trialOn) {
    rule = 'אם הספר אומר כן או רוצה לראות: כתוב משהו כמו "סבבה, אני שולח לך את הלינק עוד מעט", agreed = true, action = "handoff".';
  } else {
    rule = 'אם הספר אומר כן או רוצה לראות (agreed = true): '
      + (c.mobile
        ? 'הנייד שלו ידוע (' + c.mobile + '). כתוב משהו כמו "סבבה, עוד כמה דקות אני שולח לך את הלינק" ו-action = "trial".'
        : 'שאל בקצרה לאיזה מספר נייד לחבר לו את הצד של הניהול (action = "continue"). כשהוא נותן מספר, כתוב משהו כמו "סבבה, עוד כמה דקות אני שולח לך את הלינק", mobile = המספר ו-action = "trial".')
      + (c.agreed ? ' (הוא כבר הסכים קודם בשיחה.)' : '');
  }
  return { json: { ...it.json, prompt: 'השיחה עד עכשיו:\n' + transcript + '\n\nמצב: ' + rule + '\n\nכתוב את ההודעה הבאה של אביב.' } };
});

// מפרק את תשובת ה-AI, מעדכן את מצב השיחה ומפצל לשליחה / התראה.
const state = $getWorkflowStaticData('global');
const out = [];
const prompts = $('בניית בקשה').all();
$input.all().forEach((it, idx) => {
  const { igsid, notifyOnly } = prompts[idx]?.json || {};
  const c = state.convos[igsid];
  if (!c) return;
  if (notifyOnly) {
    out.push({ json: { kind: 'notify', igsid, reason: 'הספר כתב שוב בשיחה שמחכה לך', summary: c.summary || '', last: c.history.at(-1)?.text || '' } });
    return;
  }
  let r;
  try {
    const raw = it.json.candidates?.[0]?.content?.parts?.map((p) => p.text).join('') || '';
    r = JSON.parse(raw.replace(/^```(json)?|```$/g, '').trim());
  } catch (e) {
    r = { messages: [], action: 'handoff', reason: 'ה-AI לא החזיר תשובה תקינה: ' + (it.json.error?.message || e.message) };
  }
  const messages = (r.messages || []).slice(0, 2)
    .map((m) => String(m).replace(/[\u2014\u2013]/g, '-').replace(/[!?]+/g, '').replace(/,(?!\d)/g, '').replace(/(?<!\d)\.(?=\s|$)/g, '').trim())
    .filter(Boolean);
  for (const m of messages) {
    c.history.push({ who: 'אביב', text: m });
    c.botTexts.push(m);
    out.push({ json: { kind: 'send', igsid, text: m } });
  }
  c.botTexts = c.botTexts.slice(-10);
  c.summary = r.summary || c.summary;
  if (r.agreed) c.agreed = true;
  const mob = String(r.mobile || '').replace(/\D/g, '').replace(/^972/, '0');
  if (/^05\d{8}$/.test(mob)) c.mobile = mob.slice(0, 3) + '-' + mob.slice(3);
  if (r.action === 'trial') {
    if (c.mobile && !c.trialSlug && !c.trialPending) {
      c.trialPending = true;
      out.push({ json: { kind: 'trial', igsid, mobile: c.mobile } });
    } else if (!c.mobile) {
      r.action = 'handoff';
      r.reason = 'הספר רוצה לנסות אבל אין לנו מספר נייד שלו';
    }
  }
  if (r.action === 'handoff') {
    c.status = 'handoff';
    out.push({ json: { kind: 'notify', igsid, reason: r.reason || 'צריך אותך', summary: c.summary || '', last: c.history.filter((h) => h.who === 'ספר').at(-1)?.text || '' } });
  } else if (r.action === 'optout') {
    c.status = 'optout';
  }
});
return out;

