// בונה את ההגדרות של האפליקציה לספר הזה מגוגל מפות ומהאינסטגרם שלו.
const cfg = $('Config').first().json;
const state = $getWorkflowStaticData('global');
const HAIR = ['barber_shop', 'hair_salon', 'hair_care', 'beauty_salon'];
const trial = $('לשלוח או להתריע?').item.json;
const profile = $('פרופיל אינסטגרם').item.json;
const place = ($json.places || []).find((p) => (p.types || []).some((t) => HAIR.includes(t)));
const c = state.convos[trial.igsid];
if (!place) {
  c.trialPending = false;
  c.status = 'handoff';
  return { json: { ok: false, igsid: trial.igsid, text: '⚠️ ספר רוצה לנסות, אבל לא מצאתי את המספרה שלו בגוגל מפות (חיפשתי: ' + (profile.name || profile.username) + '). הנייד שלו: ' + trial.mobile + '. צריך לפתוח לו ידנית. https://instagram.com/' + (profile.username || '') } };
}
const barber = place.primaryType === 'barber_shop' || /ברבר|barber|גבר/i.test(place.displayName?.text || '');
let slug = String(profile.username || place.displayName?.text || 'shop').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 30);
if (slug.length < 2) slug = 'shop-' + slug;
state.slugs = state.slugs || {};
while (state.slugs[slug] && state.slugs[slug] !== trial.igsid) slug += '-2';
state.slugs[slug] = trial.igsid;
// כתובת משלו: barber-<שם>.web.app (עד 30 תווים, ייחודי בכל Firebase). אם תפוס, האפליקציה נשארת גם ב-barber-trial.web.app/<slug>.
// כמו המספרות הקבועות: barber-<שם>.web.app
let siteId = ('barber-' + slug.replace(/^barber-?/, '')).slice(0, 30).replace(/-$/, '');

const parts = (place.formattedAddress || '').split(',').map((x) => x.trim()).filter((x) => x && x !== 'ישראל' && !/^\d{5,7}$/.test(x));
const street = parts[0] || '';
const city = (parts[1] || '').replace(/\s*\d{5,7}$/, '');
const hours = {};
for (let d = 0; d < 7; d++) hours[d] = { open: false, from: 9 * 60, to: 20 * 60 };
for (const per of place.regularOpeningHours?.periods || []) {
  const d = per.open?.day;
  if (d == null || !per.close) continue;
  const from = per.open.hour * 60 + (per.open.minute || 0);
  const to = per.close.day === d ? per.close.hour * 60 + (per.close.minute || 0) : 24 * 60 - 1;
  const h = hours[d];
  hours[d] = h.open ? { open: true, from: Math.min(h.from, from), to: Math.max(h.to, to) } : { open: true, from, to };
}
if (!Object.values(hours).some((h) => h.open)) {
  for (let d = 0; d < 5; d++) hours[d] = { open: true, from: 9 * 60, to: 20 * 60 };
  hours[5] = { open: true, from: 9 * 60, to: 14 * 60 };
}
const services = barber
  ? [
      { id: 'cut', name: 'תספורת גבר', shortName: 'תספורת', price: 70, durationMin: 30, priceHidden: false, order: 0 },
      { id: 'cut-beard', name: 'תספורת + זקן', shortName: 'תספורת + זקן', price: 100, durationMin: 45, priceHidden: false, popular: true, order: 1 },
      { id: 'beard', name: 'עיצוב וגילוח זקן', shortName: 'זקן', price: 50, durationMin: 20, priceHidden: false, order: 2 },
      { id: 'kid', name: 'תספורת ילד', shortName: 'ילד', price: 60, durationMin: 30, priceHidden: false, order: 3 },
    ]
  : [
      { id: 'cut-women', name: 'תספורת נשים', shortName: 'תספורת', price: 150, durationMin: 45, priceHidden: false, order: 0 },
      { id: 'blow', name: 'פן', shortName: 'פן', price: 80, durationMin: 30, priceHidden: false, order: 1 },
      { id: 'color', name: 'צבע', shortName: 'צבע', price: 250, durationMin: 90, priceHidden: true, popular: true, order: 2 },
      { id: 'cut-men', name: 'תספורת גבר', shortName: 'גבר', price: 70, durationMin: 30, priceHidden: false, order: 3 },
    ];
const e164 = (p) => '+972' + p.replace(/\D/g, '').replace(/^0/, '');
const admins = [trial.mobile, cfg.ADMIN_PHONE].filter(Boolean);
const days = Number(cfg.TRIAL_DAYS || 7);
const now = new Date();
const ends = new Date(now.getTime() + days * 86400000);
const brand = place.displayName?.text || profile.name || profile.username;
const config = {
  slug,
  siteId,
  brand,
  fullName: brand,
  kind: barber ? 'ברברשופ' : 'סלון',
  place: barber ? 'המספרה' : 'הסלון',
  audience: barber ? 'men' : 'all',
  tagline: '',
  address: { street, city },
  phone: place.nationalPhoneNumber || trial.mobile,
  adminPhones: admins,
  adminPhonesE164: admins.map(e164),
  instagram: profile.username || null,
  colors: { brand: '#111111', accent: '#E8C77A' },
  course: { enabled: false, details: '' },
  bookingMonthsAhead: 3,
  defaults: { services, settings: { hours, breakTime: null, vacations: [] } },
  galleryUrls: [],
  createdAt: now.toISOString(),
  trialEndsAt: ends.toISOString(),
  source: 'instagram-bot',
};
c.trialSlug = slug;
c.trialUrl = String(cfg.TRIAL_BASE_URL).replace(/\/$/, '') + '/' + slug;
c.trialSiteUrl = 'https://' + siteId + '.web.app';
c.trialEndsHe = ends.toLocaleDateString('he-IL', { timeZone: 'Asia/Jerusalem', day: 'numeric', month: 'numeric' });
c.trialPending = false;
return { json: { ok: true, igsid: trial.igsid, slug, siteId, siteUrl: c.trialSiteUrl, url: c.trialUrl, mobile: trial.mobile, brand, config: JSON.stringify(config) } };

// אחרי שהאתר עלה: שולחים לספר את הלינק ואת השבוע בחינם.
const state = $getWorkflowStaticData('global');
const out = [];
$input.all().forEach((_, i) => {
const t = $('בניית אפליקציית ניסיון').itemMatching(i).json;
const c = state.convos[t.igsid];
// אם הכתובת שלו עלתה משתמשים בה, אחרת בכתובת המשותפת.
const res = $input.all()[i].json;
const siteOk = res.statusCode === 200 && !/Site Not Found/i.test(String(res.body || res.data || ''));
if (siteOk) c.trialUrl = t.siteUrl;
t.url = c.trialUrl;
const msgs = [
  'הנה היא ' + t.url,
  'שבוע ראשון בחינם גם עם הלקוחות שלך\nנכנסים עם ' + t.mobile + ' ורואים גם את הצד של הניהול ומשם אפשר לשנות מחירים שעות ושירותים',
];
for (const m of msgs) { c.history.push({ who: 'אביב', text: m }); c.botTexts.push(m); out.push({ json: { igsid: t.igsid, text: m } }); }
});
return out;

const state = $getWorkflowStaticData('global');
const t = $input.first().json.access_token;
if (t) { state.token = t; state.tokenRefreshedAt = new Date().toISOString(); }
return [{ json: { ok: !!t, refreshedAt: state.tokenRefreshedAt } }];
